57	// What counts as shipped browser source. Deliberately NOT a hard-coded project
58	// root: every rule in this pack is gated on the speech API it judges actually
59	// appearing in the file, so the trigger is the API usage itself and the scan can
60	// safely be repo-shaped. A path scope hard-wired to one project's layout would
61	// make all three rules match zero files — and pass VACUOUSLY GREEN — in any repo
62	// laid out differently, which is the worst failure mode a check has.
63	//
64	// The one thing the scan must still exclude is test scaffolding: hand-rolled
65	// speech fakes implement only the halves of a contract a given case exercises,
66	// and holding purpose-built scaffolding to the production contract is a false
67	// alarm. That exclusion is expressed directly — by test/vendor path and test
68	// filename — instead of being a side effect of the source root.
69	const SOURCE_EXT = /\.(?:m|c)?[jt]sx?$/;
70	const NOT_SOURCE = [
71	  /(?:^|\/)(?:node_modules|dist|build|out|coverage|vendor|third_party)\//,
72	  /(?:^|\/)(?:tests?|__tests__|__mocks__|spec|fixtures?|mocks?|e2e)\//,
73	  /(?:^|[./-])(?:test|spec|fixture|mock|stub|fake)s?\.[^/]+$/,
74	];
75	export const isSource = (file) => SOURCE_EXT.test(file) && !NOT_SOURCE.some((re) => re.test(file));
76	
77	/** 1-based line number of `index` in `text`. */
78	export const lineOf = (text, index) => text.slice(0, index).split('\n').length;
79	
80	/**
81	 * Both legal ways to wire a speech event, as one matcher: the `onfoo =` property
82	 * assignment and `addEventListener('foo', …)`. The DOM offers both for every one
83	 * of these targets and neither is more correct, so a rule that knows only the
84	 * property form silently passes half the world's code — and false-alarms on a
85	 * file that mixes the two (`rec.onresult = …` beside
86	 * `rec.addEventListener('error', …)` reads as "no error handler" to a matcher
87	 * that only understands `.onerror =`).
88	 */
89	export const wires = (src, event) =>
90	  new RegExp(
91	    `\\.\\s*on${event}\\s*=|addEventListener\\s*\\(\\s*['"\`]${event}['"\`]`,
92	  ).test(src);
93	
94	/** Does `text` contain `name` as a string literal? */
95	export const quoted = (text, name) => new RegExp(`['"\`]${name}['"\`]`).test(text);
96	
97	/**
98	 * The balanced bracketed run beginning at the opener at `open` (inclusive of both
99	 * brackets), or null when the source is unbalanced — a half-written file should
100	 * make a check say nothing, never guess. String and template literals are skipped
101	 * so a bracket inside "a(b)" can't be read as syntax.
102	 */
103	export function balanced(src, open) {
104	  let depth = 0;
105	  for (let i = open; i < src.length; i++) {
106	    const c = src[i];
107	    if (c === '"' || c === "'" || c === '`') {
108	      const quote = c;
109	      for (i += 1; i < src.length; i++) {
110	        if (src[i] === '\\') { i += 1; continue; }
111	        if (src[i] === quote) break;
112	      }
113	      continue;
114	    }
115	    if (c === '{' || c === '[' || c === '(') depth += 1;
116	    else if (c === '}' || c === ']' || c === ')') {
117	      depth -= 1;
118	      if (depth === 0) return src.slice(open, i + 1);
119	    }
120	  }
121	  return null;
122	}
