1	// Red-first fixtures for the browser-speech pack's checks.
2	//
3	// Every rule is exercised three ways: it must FIRE on a violating source, stay
4	// QUIET on a clean one, and stay quiet on the repo's real extension/src/ tree.
5	// The third case is what makes the pack shippable — a check that only ever saw
6	// its own fixtures is a check nobody has confronted with real code.
7	//
8	// Runs in the project's own vitest (see the .claudinite/local/packs include in
9	// vitest.config.js) and imports nothing from the gitignored canon mount, so it
10	// works in CI exactly as it does locally.
11	
12	import { describe, test, expect } from 'vitest';
13	import { readdirSync, readFileSync, statSync } from 'node:fs';
14	import { join, relative, sep } from 'node:path';
15	
16	import pack from './pack.mjs';
17	import { isSource } from './lib.mjs';
18	import ttsSpeakSettles from './tts-speak-settles.mjs';
19	import sttTerminalHandlers from './stt-terminal-handlers.mjs';
20	import micCaptureReleased from './mic-capture-released.mjs';
21	
22	// A check context over a literal file map — the same {files, read} surface the
23	// engine's runner passes, with nothing else the rules are allowed to touch.
24	const ctxOf = (files) => ({
25	  files: Object.keys(files),
26	  read: (f) => (f in files ? files[f] : null),
27	});
28	
29	const run = (rule, files) => rule.run(ctxOf(files));
