32	  test('is a hand-declared local pack whose rules are all wired', () => {
33	    expect(pack.id).toBe('browser-speech'); // must equal the directory name
34	    expect(pack.detect).toBeNull();
35	    expect(pack.marker).toBeNull();
36	    expect(pack.prose).toBe('RULES.md');
37	    expect(pack.rules.map((r) => r.id).sort()).toEqual(
38	      ['mic-capture-released', 'stt-terminal-handlers', 'tts-speak-settles'],
