44	// project's source root matches nothing — and passes vacuously green — in a repo
45	// laid out differently, which is exactly the bug these cases exist to prevent.
46	describe('source scope', () => {
47	  test('accepts browser source under any layout, in JS and TS alike', () => {
48	    for (const file of [
49	      'extension/src/speech/stt-port.js',
50	      'src/speech.ts',
51	      'app/lib/voice.tsx',
52	      'packages/web/audio.mjs',
53	      'assistant.cjs',
