57	
58	  test('rejects test scaffolding, fixtures and vendored code wherever they sit', () => {
59	    for (const file of [
60	      'extension-test/unit/speech-ports.test.js',
61	      'src/speech.spec.ts',
62	      'test/voice.js',
63	      '__tests__/mic.js',
64	      'src/__mocks__/recognition.js',
65	      'test/fixtures/fake-recognizer.js',
66	      'node_modules/some-pkg/speech.js',
67	      'dist/bundle.js',
68	      'README.md',
69	    ]) expect(isSource(file), file).toBe(false);
70	  });
71	});
