74	  test('fires when a chrome.tts handler only resolves on end', () => {
75	    const found = run(ttsSpeakSettles, {
76	      'extension/src/speech/bad-tts.js': `
77	        export function speak(text) {
78	          return new Promise((resolve) => {
79	            chrome.tts.speak(text, {
80	              enqueue: false,
81	              onEvent(event) {
82	                if (event.type === 'end') resolve();
83	              },
84	            });
85	          });
86	        }
87	      `,
88	    });
89	    expect(found).toHaveLength(1);
90	    expect(found[0].rule).toBe('tts-speak-settles');
91	    expect(found[0].severity).toBe('blocking');
92	    expect(found[0].what).toContain('interrupted');
93	  });
94	
95	  test('fires when a SpeechSynthesisUtterance has onend but no onerror', () => {
96	    const found = run(ttsSpeakSettles, {
97	      'extension/src/speech/bad-synth.js': `
98	        const utterance = new SpeechSynthesisUtterance(text);
99	        utterance.onend = () => resolve();
100	        synth.speak(utterance);
101	      `,
102	    });
103	    expect(found).toHaveLength(1);
104	    expect(found[0].what).toContain('error');
105	  });
106	
107	  test('fires on an utterance wired for end via addEventListener but not error', () => {
108	    const found = run(ttsSpeakSettles, {
109	      'src/voice.ts': `
110	        const utterance = new SpeechSynthesisUtterance(text);
111	        utterance.addEventListener('end', () => resolve());
