116	    expect(found[0].what).toContain('error');
117	  });
118	
119	  test('stays quiet on an utterance that mixes the two wiring forms', () => {
120	    // `.onend =` beside addEventListener('error') is correctly wired; a matcher
121	    // that understood only property assignment would false-alarm here.
122	    expect(run(ttsSpeakSettles, {
123	      'src/voice.ts': `
124	        const utterance = new SpeechSynthesisUtterance(text);
125	        utterance.onend = () => resolve();
126	        utterance.addEventListener('error', () => resolve());
127	      `,
128	    })).toEqual([]);
129	  });
130	
131	  test('stays quiet on a handler that delegates to a hoisted terminal set', () => {
132	    // It enumerates nothing inline, so the rule cannot read it — and says
133	    // nothing rather than guessing. This code is correct; firing would be noise.
134	    expect(run(ttsSpeakSettles, {
135	      'src/tts.js': `
136	        const TERMINAL = new Set(['end', 'interrupted', 'cancelled', 'error']);
137	        function isDone(type) { return TERMINAL.has(type); }
138	        chrome.tts.speak(text, {
139	          onEvent(event) { if (isDone(event.type)) resolve(); },
140	        });
141	      `,
142	    })).toEqual([]);
143	  });
144	
145	  test('stays quiet on a handler that covers every terminal event', () => {
146	    expect(run(ttsSpeakSettles, {
147	      'extension/src/speech/good-tts.js': `
148	        chrome.tts.speak(text, {
149	          enqueue: false,
150	          onEvent(event) {
151	            if (['end', 'interrupted', 'cancelled', 'error'].includes(event.type)) resolve();
152	          },
153	        });
154	        const utterance = new SpeechSynthesisUtterance(text);
155	        utterance.onend = () => resolve();
156	        utterance.onerror = () => resolve();
157	      `,
158	    })).toEqual([]);
159	  });
160	
161	  test('stays quiet on a speak() call that supplies no onEvent handler', () => {
162	    // The orchestrator's own tts.speak(text, {rate}) goes through the port, which
163	    // already owns the terminal handling — holding it to this rule would be noise.
164	    expect(run(ttsSpeakSettles, {
165	      'extension/src/app/orchestrator.js': "await tts.speak(phrases.render(a.say), { rate });",
166	    })).toEqual([]);
167	  });
168	
169	  test('stays quiet when the only mention of the trap is a comment', () => {
170	    expect(run(ttsSpeakSettles, {
171	      'extension/src/speech/note.js': `
172	        // chrome.tts.speak(text, { onEvent(e) { if (e.type === 'end') resolve(); } })
173	        export const NOTE = 1;
174	      `,
175	    })).toEqual([]);
176	  });
177	});
